void Update()
{
    if (Input.GetKeyDown(KeyCode.G))
        Debug.Log("G pressed!");
    if (Input.GetKey(KeyCode.G))
        Debug.Log("Holding G...");
    if (Input.GetKeyUp(KeyCode.G))
        Debug.Log("G released!");
}
